SELECT FROM forum_badge b WHERE b.status='PUBLISHED'
AND b.rule_type IN #{ruleType}
ORDER BY b.sort_no,b.id

SELECT ,DATE_FORMAT(mb.awarded_at,'%Y-%m-%d %H:%i:%s') AS awardedAt
FROM forum_badge b JOIN forum_member_badge mb ON mb.badge_id=b.id AND mb.account_id=#{accountId}
ORDER BY mb.awarded_at DESC,mb.id DESC LIMIT #{limit}
